    return user

@app.put("/users/{user_id}")
async def update_user(user_id: int, user: User):
    for u in users:
        if u["id"] == user_id:
            u["name"] = user.name
            u["email"] = user.email
            return user
    return {"error": "User not found"}

@app.delete("/users/{user_id}")
