from fastapi import FastAPI, Depends
from pydantic import BaseModel
import elasticsearch as es

app = FastAPI()

# Elasticsearch settings
ES_HOST = "localhost"
ES_PORT = 9200
ES_INDEX = "my_index"

es_client = es.Elasticsearch(hosts=[f"{ES_HOST}:{ES_PORT}"])

class User(BaseModel):
    id: int
    name: str
    email: str

@app.get("/users/")
async def read_users():
    # Get users from Elasticsearch
    response = es_client.search(index=ES_INDEX, body={"query": {"match_all": {}}})
    users = response["hits"]["hits"]
    return users

@app.get("/users/{user_id}")
async def read_user(user_id: int):
    # Get user from Elasticsearch
    response = es_client.search(index=ES_INDEX, body={"query": {"match": {"id": user_id}}})
    user = response["hits"]["hits"][0]
    return user

@app.post("/users/")
async def create_user(user: User):
    # Create user in Elasticsearch
    es_client.index(index=ES_INDEX, body=user.dict())
    return user

@app.put("/users/{user_id}")
async def update_user(user_id: int, user: User):
    # Update user in Elasticsearch
    response = es_client.search(index=ES_INDEX, body={"query": {"match": {"id": user_id}}})
    user_data = response["hits"]["hits"][0]
    user_data["_source"] = user.dict()
    es_client.update(index=ES_INDEX, id=user_id, body=user_data)
    return user

@app.delete("/users/{user_id}")
async def delete_user(user_id: int):
    # Delete user from Elasticsearch
    es_client.delete(index=ES_INDEX, id=user_id)
    return {"message": "User deleted"}
