**FastAPI Application Code**

```python
# main.py
from fastapi import FastAPI, Depends, HTTPException
from fastapi.responses import JSONResponse
from fastapi.requests import Request
from pydantic import BaseModel
from sqlalchemy import create_engine, Column, Integer, String, Float, DateTime
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
import redis
import uvicorn

app = FastAPI()

# Database configuration
SQLALCHEMY_DATABASE_URL = "postgres://username:password@localhost:5432/database"
redis_client = redis.Redis(host="localhost", port=6379, db=0)

# Database models
Base = declarative_base()

class Product(Base):
    __tablename__ = "products"
    id = Column(Integer, primary_key=True)
    name = Column(String)
    price = Column(Float)
    description = Column(String)

class User(Base):
    __tablename__ = "users"
    id = Column(Integer, primary_key=True)
    name = Column(String)
    email = Column(String)

class Order(Base):
    __tablename__ = "orders"
    id = Column(Integer, primary_key=True)
    user_id = Column(Integer)
    product_id = Column(Integer)
    created_at = Column(DateTime)

# Create database engine and session
engine = create_engine(SQLALCHEMY_DATABASE_URL)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

# Redis caching
cache = redis_client

# FastAPI routing
@app.get("/products")
async def read_products(skip: int = 0, limit: int = 100, name: str = None):
    session = SessionLocal()
    products = session.query(Product).offset(skip).limit(limit).all()
    if name:
        products = [p for p in products if p.name.lower().startswith(name.lower())]
    return products

@app.get("/products/{product_id}")
async def read_product(product_id: int):
    session = SessionLocal()
    product = session.query(Product).get(product_id)
    if not product:
        raise HTTPException(status_code=404, detail="Product not found")
    return product

@app.post("/orders")
async def create_order(order: Order):
    # Validate order data
    if not order.user_id or not order.product_id:
        raise HTTPException(status_code=400, detail="Invalid order data")
    session = SessionLocal()
    try:
        # Create order
        session.add(order)
        session.commit()
        return {"message": "Order created successfully"}
    except Exception as e:
        # Handle error
        session.rollback()
        raise HTTPException(status_code=500, detail=str(e))

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
