# app/config.py
import pyhystrix

class CircuitBreaker:
    def __init__(self, name, fallback):
        self.name = name
        self.fallback = fallback
        self.hystrix = pyhystrix.Hystrix(name, fallback)

    def is_open(self):
        return self.hystrix.is_open()

    def execute(self, func):
        if self.is_open():
            return self.fallback()
        else:
            return func()
