from fastapi import FastAPI
from fastapi.responses import JSONResponse
from pybreaker import CircuitBreaker
from hystrix import HystrixCommand
from loguru import logger
import random

app = FastAPI()

# Initialize circuit breaker
breaker = CircuitBreaker(fail_max=5, reset_timeout=10)

# Fallback strategy for /products endpoint
class ProductsFallback(HystrixCommand):
    def __init__(self):
        super().__init__(name="products", fallback=lambda *args, **kwargs: {"products": []})

    def run(self):
        # Simulate external service failure with 20% chance
        if random.random() < 0.2:
            raise Exception("External service failure")
        return [{"id": 1, "name": "Product 1"}, {"id": 2, "name": "Product 2"}]

# Fallback strategy for /orders endpoint
class OrdersFallback(HystrixCommand):
    def __init__(self):
        super().__init__(name="orders", fallback=lambda *args, **kwargs: {"message": "Payment gateway unavailable"})

    def run(self):
        # Simulate external payment gateway failure with 30% chance
        if random.random() < 0.3:
            raise Exception("Payment gateway failure")
        return {"message": "Order created successfully"}

# Fallback strategy for /inventory endpoint
class InventoryFallback(HystrixCommand):
    def __init__(self):
        super().__init__(name="inventory", fallback=lambda *args, **kwargs: {"message": "Inventory system unavailable"})

    def run(self):
        # Simulate external inventory management system failure with 10% chance
        if random.random() < 0.1:
            raise Exception("Inventory system failure")
        return {"message": "Inventory updated successfully"}

# /products endpoint with circuit breaking and Hystrix fallback
@app.get("/products")
async def get_products():
    try:
        # Call external service with circuit breaker
        with breaker:
            return {"products": [ProductsFallback().execute().products]}
    except Exception as e:
        # Catch and log exceptions
        logger.error(f"Error getting products: {e}")
        return JSONResponse(status_code=500, content={"error": "Internal Server Error"})

# /orders endpoint with circuit breaking and Hystrix fallback
@app.post("/orders")
async def create_order():
    try:
        # Call external payment gateway with circuit breaker
        with breaker:
            return {"order": OrdersFallback().execute().message}
    except Exception as e:
        # Catch and log exceptions
        logger.error(f"Error creating order: {e}")
        return JSONResponse(status_code=500, content={"error": "Internal Server Error"})

# /inventory endpoint with circuit breaking and Hystrix fallback
@app.put("/inventory")
async def update_inventory():
    try:
        # Call external inventory management system with circuit breaker
        with breaker:
            return {"message": InventoryFallback().execute().message}
    except Exception as e:
        # Catch and log exceptions
        logger.error(f"Error updating inventory: {e}")
        return JSONResponse(status_code=500, content={"error": "Internal Server Error"})
