from etcd import Client
from consul import Consul

class ServiceDiscovery:
    def __init__(self):
        self.etcd_client = Client(host='localhost', port=2379)
        self.consul_client = Consul(host='localhost', port=8500)

    def get_services_etcd(self):
        try:
            services = self.etcd_client.get('/services', recursive=True)
            services = json.loads(services[1])
            return services
        except Exception as e:
            raise e

    def get_services_consul(self):
        try:
            services = self.consul_client.health.service('your_service_name')
            return services
        except Exception as e:
            raise e

    def register_service_etcd(self, ip, port, instance_id):
        try:
            self.etcd_client.put('/services/{}'.format(ip), '{{"ip": "{}", "port": {}, "instance_id": "{}"}}'.format(ip, port, instance_id))
        except Exception as e:
            raise e

    def deregister_service_etcd(self, ip, port, instance_id):
        try:
            self.etcd_client.delete('/services/{}'.format(ip))
        except Exception as e:
            raise e

    def register_service_consul(self, ip, port, instance_id):
        try:
            self.consul_client.agent.service.register(name='your_service_name', address=ip, port=port, tags=['{}:{}'.format(ip, instance_id)])
        except Exception as e:
            raise e

    def deregister_service_consul(self, ip, port, instance_id):
        try:
            self.consul_client.agent.service.deregister('your_service_name')
        except Exception as e:
            raise e
