logging.basicConfig(
    format="%(asctime)s %(levelname)s [%(request_id)s] [%(user_id)s] %(message)s",
    level=logging.INFO,
    datefmt="%Y-%m-%d %H:%M:%S"
)

logger = logging.getLogger(__name__)

def log_request(request: Request, level: str):
    logger.log(getattr(logging, level.upper()), f"[{request.id}] [{request.user_id}] {request.method} {request.path}")

@app.middleware("http")
async def request_id(request: Request, call_next):
    request_id = uuid.uuid4()
    request.state.request_id = request_id
    response = await call_next(request)
    log_request(request, "info")
    return response
