@app.get("/users/")
async def read_users():
    db = SessionLocal()
    users = db.query(User).all()
    db.close()
    return {"users": users}

@app.post("/users/")
async def create_user(user: User):
    db = SessionLocal()
    db.add(user)
    db.commit()
    db.refresh(user)
