SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

# Define JWT secret key
SECRET_KEY = "secret_key"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 30

# Define authentication dependencies
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

def authenticate_user(db, username: str, password: str):
    user = db.query(User).filter(User.username == username).first()
    if not user:
        return False
    if not verify_password(password, user.password):
        return False
    return user

def get_current_user(token: str = Depends(oauth2_scheme)):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username: str = payload.get("sub")
        if username is None:
            raise HTTPException(status_code=401, detail="Could not validate credentials")
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Access token expired")
    except jwt.JWTClaimsError:
        raise HTTPException(status_code=401, detail="Invalid JWT claims")
    except jwt.JWTError:
        raise HTTPException(status_code=401, detail="Invalid JWT")
    db = next(get_db())
    user = db.query(User).filter(User.username == username).first()
    db.close()
    if user is None:
        raise HTTPException(status_code=401, detail="User not found")
    return user

# Define routes
@app.post("/token")
async def login(form_data: OAuth2PasswordRequestForm = Depends()):
    user = authenticate_user(get_db(), form_data.username, form_data.password)
    if not user:
        raise HTTPException(status_code=401, detail="Incorrect username or password")
    access_token_expires = timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    access_token = create_access_token(
        data={"sub": user.username}, expires_delta=access_token_expires
    )
    return {"access_token": access_token, "token_type": "bearer"}

@app.get("/tasks/", response_model=List[Task])
async def read_tasks(current_user: User = Depends(get_current_user)):
    db = next(get_db())
    tasks = db.query(Task).all()
    db.close()
    return tasks

@app.post("/tasks/", response_model=Task)
async def create_task(task: Task, current_user: User = Depends(get_current_user)):
    db = next(get_db())
    db.add(task)
    db.commit()
    db.close()
    return task

@app.put("/tasks/{task_id}", response_model=Task)
async def update_task(task_id: int, task: Task, current_user: User = Depends(get_current_user)):
    db = next(get_db())
    task_db = db.query(Task).filter(Task.id == task_id).first()
    if task_db is None:
        raise HTTPException(status_code=404, detail="Task not found")
    task_db.title = task.title
    task_db.description = task.description
    db.commit()
    db.close()
    return task

@app.delete("/tasks/{task_id}")
async def delete_task(task_id: int, current_user: User = Depends(get_current_user)):
    db = next(get_db())
    task_db = db.query(Task).filter(Task.id == task_id).first()
    if task_db is None:
        raise HTTPException(status_code=404, detail="Task not found")
    db.delete(task_db)
    db.commit()
    db.close()
    return {"message": "Task deleted"}
