engine = create_engine('postgresql://user:password@host:port/dbname')

@app.post('/orders')
def create_order(order):
    # Create order in database
    engine.execute('INSERT INTO orders (product_id, customer_id) VALUES (:product_id, :customer_id)', order)
    return order

@app.put('/orders')
def update_order(order):
    # Update order in database
    engine.execute('UPDATE orders SET status = :status WHERE id = :id', order)
    return order

@app.delete('/orders')
def cancel_order(order):
    # Cancel order in database
    engine.execute('DELETE FROM orders WHERE id = :id', order)
    return order
