from fastapi import FastAPI
from pydantic import BaseModel
from sqlalchemy import create_engine
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

app = FastAPI()

engine = create_engine('postgresql://user:password@postgresql:5432/db')
Session = sessionmaker(bind=engine)
Base = declarative_base()

class Item(Base):
    __tablename__ = 'items'
    id = Column(Integer, primary_key=True)
    name = Column(String)
    price = Column(Float)

Base.metadata.create_all(engine)

class ItemBase(BaseModel):
    name: str
    price: float

@app.get("/")
async def read_root():
    return {"message": "Hello, World!"}

@app.get("/items/")
async def read_items():
    session = Session()
    items = session.query(Item).all()
    return [{"id": i.id, "name": i.name, "price": i.price} for i in items]

@app.post("/items/")
async def create_item(item: ItemBase):
    session = Session()
    new_item = Item(name=item.name, price=item.price)
    session.add(new_item)
    session.commit()
    return {"message": "Item created"}

@app.put("/items/{item_id}")
async def update_item(item_id: int, item: ItemBase):
    session = Session()
    existing_item = session.query(Item).filter(Item.id == item_id).first()
    if existing_item:
        existing_item.name = item.name
        existing_item.price = item.price
        session.commit()
        return {"message": "Item updated"}
    return {"message": "Item not found"}

@app.delete("/items/{item_id}")
async def delete_item(item_id: int):
    session = Session()
    session.query(Item).filter(Item.id == item_id).delete()
    session.commit()
    return {"message": "Item deleted"}
