from fastapi import FastAPI, Depends
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from pydantic import BaseModel

app = FastAPI()

# Define the database connection string
DB_CONN_STR = "postgresql://user:password@localhost/book_db"

# Create a SQLAlchemy engine and session maker
engine = create_engine(DB_CONN_STR)
Session = sessionmaker(bind=engine)

# Define a Pydantic model for books
class Book(BaseModel):
    id: int
    title: str
    author: str

# Define a CRUD API for books
@app.get("/books/")
def read_books():
    session = Session()
    books = session.query(Book).all()
    return [{"id": book.id, "title": book.title, "author": book.author} for book in books]

@app.post("/books/")
def create_book(book: Book):
    session = Session()
    session.add(book)
    session.commit()
    return {"message": "Book created successfully"}

@app.get("/books/{book_id}")
def read_book(book_id: int):
    session = Session()
    book = session.query(Book).get(book_id)
    if book:
        return {"id": book.id, "title": book.title, "author": book.author}
    return {"message": "Book not found"}

@app.put("/books/{book_id}")
def update_book(book_id: int, book: Book):
    session = Session()
    book_to_update = session.query(Book).get(book_id)
    if book_to_update:
        book_to_update.title = book.title
        book_to_update.author = book.author
        session.commit()
        return {"message": "Book updated successfully"}
    return {"message": "Book not found"}

@app.delete("/books/{book_id}")
def delete_book(book_id: int):
    session = Session()
    book_to_delete = session.query(Book).get(book_id)
    if book_to_delete:
        session.delete(book_to_delete)
        session.commit()
        return {"message": "Book deleted successfully"}
    return {"message": "Book not found"}
