async def healthcheck():
    return {"status": "ok"}

@app.post("/login")
async def login(form_data: OAuth2PasswordRequestForm = Depends()):
    username = form_data.username
    password = form_data.password
    if username not in tokens or tokens[username] != password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    access_token_expires = datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    access_token = jwt.encode({"sub": username, "exp": access_token_expires}, SECRET_KEY, algorithm=ALGORITHM)
    return {"access_token": access_token, "token_type": "bearer"}

@app.get("/protected")
async def protected(token: str = Depends(oauth2_scheme)):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username = payload["sub"]
        return {"username": username, "message": "Hello, " + username}
    except JWTError:
        raise HTTPException(status_code=401, detail="Invalid token")

@app.websocket("/ws")
async def websocket_endpoint(websocket: websockets.WebSocketServerProtocol, token: str = Depends(oauth2_scheme)):
    await websocket.accept()
    try:
        while True:
            message = await websocket.receive()
            await websocket.send_message(message.text)
    except websockets.ConnectionClosed:
        pass

# Celery tasks
@celery_app.task
def broadcast_message(message):
    # Send message to WebSocket clients
    async def broadcast():
        async with websockets.connect("ws://localhost:8001/ws") as websocket:
            await websocket.send(message)

    asyncio.run(broadcast())
