# Prometheus metrics
active_users = Gauge('active_users', 'The number of active users')
products_in_db = Gauge('products_in_db', 'The number of products in the database')
checkout_requests_per_minute = Counter('checkout_requests_per_minute', 'The number of checkout requests per minute')
average_response_time = Histogram('average_response_time', 'The average response time of the checkout endpoint')
failed_login_attempts = Counter('failed_login_attempts', 'The number of failed login attempts per hour')

def get_user_from_db(session, username):
    return session.query(User).filter(User.username == username).first()

def add_product_to_cart(session, cart):
    session.add(cart)
    session.commit()

def create_order(session, order):
    session.add(order)
    session.commit()

@app.get("/users/{username}")
async def read_user(username: str):
    session = Session()
    user = get_user_from_db(session, username)
    if user:
        active_users.set(1)
    else:
        active_users.set(0)
    return JSONResponse(content={"message": f"User {username} found"}, status_code=200)

@app.get("/products")
async def read_products():
    session = Session()
    products = session.query(Product).all()
    products_in_db.set(len(products))
    return JSONResponse(content={"products": [{"id": p.id, "name": p.name, "price": p.price} for p in products]})

@app.post("/cart")
async def add_to_cart(cart: Cart):
    session = Session()
    add_product_to_cart(session, cart)
    return JSONResponse(content={"message": f"Product added to cart"}, status_code=201)

@app.post("/checkout")
async def checkout(order: Order):
    start_time = datetime.now()
    try:
        session = Session()
        create_order(session, order)
        end_time = datetime.now()
        response_time = (end_time - start_time).total_seconds()
        average_response_time.observe(response_time)
        return JSONResponse(content={"message": f"Checkout successful"}, status_code=200)
    except Exception as e:
        failed_login_attempts.inc()
        return JSONResponse(content={"message": f"Checkout failed"}, status_code=500)

@app.post("/login")
async def login(username: str, password: str):
    session = Session()
    user = get_user_from_db(session, username)
    if user and user.password == password:
        return JSONResponse(content={"message": f"Login successful"}, status_code=200)
    else:
        failed_login_attempts.inc()
        return JSONResponse(content={"message": f"Login failed"}, status_code=401)

