### FastAPI Backend

**`main.py`**
```python
from fastapi import FastAPI
from pydantic import BaseModel
from sqlalchemy import create_engine, Column, Integer, String
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

app = FastAPI()

# Database configuration
SQLALCHEMY_DATABASE_URL = "postgresql://user:password@host:port/database"

# Create database engine
engine = create_engine(SQLALCHEMY_DATABASE_URL)

# Create a configured "Session" class
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

# Base class for declarative models
Base = declarative_base()

# Book model
class Book(Base):
    __tablename__ = "books"
    id = Column(Integer, primary_key=True)
    title = Column(String)
    author = Column(String)

# Create a database session
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

# API endpoints
@app.get("/books/")
def read_books():
    db = next(get_db())
    books = db.query(Book).all()
    return [{"id": book.id, "title": book.title, "author": book.author} for book in books]

@app.post("/books/")
def create_book(book: Book):
    db = next(get_db())
    db.add(book)
    db.commit()
    db.refresh(book)
    return {"id": book.id, "title": book.title, "author": book.author}

@app.put("/books/")
def update_book(book: Book):
    db = next(get_db())
    db.query(Book).filter(Book.id == book.id).update({"title": book.title, "author": book.author})
    db.commit()
    return {"id": book.id, "title": book.title, "author": book.author}

@app.delete("/books/")
def delete_book(book_id: int):
    db = next(get_db())
    db.query(Book).filter(Book.id == book_id).delete()
    db.commit()
    return {"message": "Book deleted"}
```

