import React, { useState, useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { fetchCostData, fetchAllocationTags, generateRecommendations } from "./actions";

function Dashboard() {
  const costData = useSelector((state) => state.costData);
  const allocationTags = useSelector((state) => state.allocationTags);
  const recommendations = useSelector((state) => state.recommendations);
  const dispatch = useDispatch();

  useEffect(() => {
    dispatch(fetchCostData());
    dispatch(fetchAllocationTags());
    dispatch(generateRecommendations());
  }, [dispatch]);

  return (
    <div>
      <h1>Cloud Cost Optimizer Dashboard</h1>
      <h2>Cost Data</h2>
      <ul>
        {costData.map((cost) => (
          <li key={cost.account_id}>{cost.account_id} - {cost.cost}</li>
        ))}
      </ul>
      <h2>Allocation Tags</h2>
      <ul>
        {allocationTags.map((tag) => (
          <li key={tag.id}>{tag.name} - {tag.description}</li>
        ))}
      </ul>
      <h2>Optimization Recommendations</h2>
      <ul>
        {recommendations.map((recommendation) => (
          <li key={recommendation.id}>{recommendation.message}</li>
        ))}
      </ul>
    </div>
  );
}

export default Dashboard;
```

