class Book(Base):
    __tablename__ = "books"
    id = Column(Integer, primary_key=True)
    title = Column(String)
    author = Column(String)

# Create a Pydantic model for the Book
class BookModel(BaseModel):
    title: str
    author: str

# Create a route for listing books
@app.get("/books/")
def list_books():
    session = sessionmaker(bind=engine)()
    books = session.query(Book).all()
    return [{"id": book.id, "title": book.title, "author": book.author} for book in books]

# Create a route for creating a new book
@app.post("/books/")
def create_book(book: BookModel):
    session = sessionmaker(bind=engine)()
    book = Book(title=book.title, author=book.author)
    session.add(book)
    session.commit()
    return {"id": book.id, "title": book.title, "author": book.author}

# Create a route for updating a book
@app.put("/books/{book_id}")
def update_book(book_id: int, book: BookModel):
    session = sessionmaker(bind=engine)()
    book = session.query(Book).get(book_id)
    if book:
        book.title = book.title
        book.author = book.author
        session.commit()
        return {"id": book.id, "title": book.title, "author": book.author}
    return {"error": "Book not found"}

# Create a route for deleting a book
@app.delete("/books/{book_id}")
def delete_book(book_id: int):
    session = sessionmaker(bind=engine)()
    book = session.query(Book).get(book_id)
    if book:
        session.delete(book)
        session.commit()
        return {"message": "Book deleted"}
    return {"error": "Book not found"}
