Implement the FastAPI backend in `main.py`:

```python
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from prometheus_client import Counter, Gauge

app = FastAPI()

# Define a custom metric for CPU utilization
cpu_utilization = Gauge('cpu_utilization', 'CPU utilization')

# Define a counter for request latency
request_latency = Counter('request_latency', 'Request latency in seconds')

# Define a health check endpoint
@app.get('/health')
def health():
    return {'status': 'ok'}

# Define an endpoint for handling CPU-intensive tasks
@app.get('/cpu-intensive')
def cpu_intensive():
    import time
    start_time = time.time()
    while time.time() - start_time < 10:
        # Simulate CPU-intensive task
        cpu_utilization.inc()
        time.sleep(0.1)
    return {'message': 'CPU-intensive task completed'}

# Define a middleware to track request latency
class RequestLatencyMiddleware:
    def __init__(self, app):
        self.app = app

    async def __call__(self, request: Request):
        start_time = time.time()
        response = await self.app(request)
        request_latency.labels(response.status_code).inc(time.time() - start_time)
        return response
```

