  const [requestLatency, setRequestLatency] = React.useState(0);

  const handleCpuIntensiveClick = async () => {
    await axios.get('/cpu-intensive');
  };

  const handleHealthClick = async () => {
    await axios.get('/health');
  };

  React.useEffect(() => {
    const intervalId = setInterval(async () => {
      try {
        const response = await axios.get('/metrics');
        const data = response.data;
        setCpuUtilization(data.cpu_utilization.value);
        setRequestLatency(data.request_latency.value);
      } catch (error) {
        console.error(error);
      }
    }, 1000);
    return () => clearInterval(intervalId);
  }, []);

  return (
    <div>
      <h1>CPU Utilization: {cpuUtilization}%</h1>
      <h2>Request Latency: {requestLatency} seconds</h2>
      <button onClick={handleCpuIntensiveClick}>CPU-Intensive Task</button>
