    return db_book

# Define a route for updating a book
@app.put("/books/{book_id}", response_model=Book)
def update_book(book_id: int, book: Book, db: SessionLocal = Depends(get_db)):
    db_book = db.query(Book).filter(Book.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    db_book.title = book.title
    db_book.author = book.author
    db_book.publication_date = book.publication_date
    db_book.isbn = book.isbn
    db.commit()
    db.refresh(db_book)
    return db_book

# Define a route for deleting a book
@app.delete("/books/{book_id}")
def delete_book(book_id: int, db: SessionLocal = Depends(get_db)):
    db_book = db.query(Book).filter(Book.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    db.delete(db_book)
