from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from pydantic import BaseModel
from jose import jwt, JWTError
from passlib.context import CryptContext
from okta import OktaClient
from okta.oauth import OAuth2Client

# Create the FastAPI application
app = FastAPI()

# Define the Okta client
okta_client = OktaClient("https://your-okta-domain.okta.com")

# Define the OAuth2 client
oauth2_client = OAuth2Client(okta_client, "your-client-id", "your-client-secret")

# Define the password context
pwd_context = CryptContext(schemes=["bcrypt"], default="bcrypt")

# Define the user model
class User(BaseModel):
    email: str
    name: str
    role: str

# Define the token model
class Token(BaseModel):
    access_token: str
    token_type: str

# Define the protected routes
protected_routes = {
    "/admin": ["admin"],
    "/moderator": ["moderator", "admin"],
    "/user": ["user", "moderator", "admin"]
}

# Define the authentication endpoint
@app.post("/login", response_model=Token)
async def login(form_data: OAuth2PasswordRequestForm = Depends()):
    # Authenticate the user using Okta
    token = oauth2_client.authenticate(form_data.username, form_data.password)
    # Generate a JWT token
    user = await get_user(token)
    access_token = jwt.encode(
        {"email": user.email, "name": user.name, "role": user.role},
        "your-secret-key",
        algorithm="HS256"
    )
    return {"access_token": access_token, "token_type": "bearer"}

# Define the protected routes
for route, roles in protected_routes.items():
    # Define the decorator for the route
    def protected(route=route, roles=roles):
        def decorator(func):
            async def wrapper(*args, **kwargs):
                # Get the access token from the request headers
                token = kwargs.get("access_token")
                # Verify the JWT token
                try:
                    payload = jwt.decode(token, "your-secret-key", algorithms=["HS256"])
                    # Check if the user has the required role
                    if payload["role"] in roles:
                        return await func(*args, **kwargs)
                    else:
                        raise HTTPException(status_code=403, detail="Forbidden")
                except JWTError:
                    raise HTTPException(status_code=401, detail="Unauthorized")
            return wrapper
        return decorator
    # Add the decorator to the route
    app.get(route, protected)(get_user)

# Define the get_user function
async def get_user(token):
    # Get the user from the JWT token
    user = User(email="user@example.com", name="John Doe", role="user")
    return user
