**FastAPI Backend**

The FastAPI backend is responsible for exposing RESTful APIs for product data and shopping cart management.

**`app/main.py`**
```python
from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from pydantic import BaseModel
from sqlalchemy import create_engine
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
import jwt
import uvicorn

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

Base = declarative_base()

class User(Base):
    __tablename__ = "users"
    id = Column(Integer, primary_key=True)
    username = Column(String)
    email = Column(String)
    password = Column(String)

class Product(Base):
    __tablename__ = "products"
    id = Column(Integer, primary_key=True)
    name = Column(String)
    price = Column(Float)

engine = create_engine("sqlite:///database.db")
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

Base.metadata.create_all(engine)

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

@app.post("/token")
async def login_for_access_token(form_data: OAuth2PasswordRequestForm = Depends()):
    user = User.query.filter_by(username=form_data.username).first()
    if not user:
        raise HTTPException(status_code=401, detail="Incorrect username or password")
    if not user.password:
        raise HTTPException(status_code=401, detail="Incorrect username or password")
    access_token = jwt.encode({"sub": user.username}, "secret_key", algorithm="HS256")
    return {"access_token": access_token, "token_type": "bearer"}

@app.get("/products/")
def read_products(db: SessionLocal = Depends(get_db)):
    return db.query(Product).all()

@app.get("/products/{product_id}")
def read_product(product_id: int, db: SessionLocal = Depends(get_db)):
    return db.query(Product).filter(Product.id == product_id).first()

@app.post("/cart/")
def add_to_cart(product_id: int, db: SessionLocal = Depends(get_db)):
    product = db.query(Product).filter(Product.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Product not found")
    return {"message": f"Added product {product.name} to cart"}

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
```
