# Create a JWT token
async def create_access_token(data: dict, expires_delta: timedelta):
    to_encode = data.copy()
    expire = datetime.utcnow() + expires_delta
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)
    return encoded_jwt

# Protected endpoint
async def get_current_user(token: str = Depends(oauth2_scheme)):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        token_data = payload
    except:
        return None
    return token_data

# OAuth2 token endpoint
@app.post("/token")
async def login(form_data: OAuth2PasswordRequestForm = Depends()):
    user = form_data.username
    token = await create_access_token(data={"sub": user}, expires_delta=timedelta(minutes=30))
    return {"access_token": token, "token_type": "bearer"}

# CRUD endpoints
@app.get("/books/")
async def read_books(current_user: dict = Depends(get_current_user)):
    return books

@app.get("/books/{book_id}")
async def read_book(book_id: int, current_user: dict = Depends(get_current_user)):
    for book in books:
        if book.id == book_id:
            return book
    return None

@app.post("/books/")
async def create_book(book: Book, current_user: dict = Depends(get_current_user)):
    books.append(book)
    return book

@app.put("/books/{book_id}")
async def update_book(book_id: int, book: Book, current_user: dict = Depends(get_current_user)):
    for b in books:
        if b.id == book_id:
            b.title = book.title
            b.author = book.author
            return b
    return None

@app.delete("/books/{book_id}")
async def delete_book(book_id: int, current_user: dict = Depends(get_current_user)):
    global books
    for book in books:
        if book.id == book_id:
            books.remove(book)
            return book
    return None
