```python
# main.py
from fastapi import FastAPI, Depends, HTTPException
from pydantic import BaseModel
from sqlalchemy import create_engine
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

# Define the database connection
SQLALCHEMY_DATABASE_URL = "postgresql://user:password@host:5432/database"

# Create a database connection engine
engine = create_engine(SQLALCHEMY_DATABASE_URL)

# Create a session maker
SessionLocal = sessionmaker(bind=engine, autoflush=False, expire_on_commit=False)

# Define a base model for the database tables
Base = declarative_base()

# Define a model for the books
class Book(Base):
    __tablename__ = "books"
    id = Column(Integer, primary_key=True)
    title = Column(String)
    author = Column(String)
    publication_date = Column(String)

# Define a schema for the book model
class BookSchema(BaseModel):
    title: str
    author: str
    publication_date: str

# Define a FastAPI app
app = FastAPI()

# Define a dependency function to get a database session
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

# Define API endpoints for creating, reading, updating, and deleting books
@app.post("/books/", response_model=BookSchema)
def create_book(book: BookSchema, db: SessionLocal = Depends(get_db)):
    db_book = Book(title=book.title, author=book.author, publication_date=book.publication_date)
    db.add(db_book)
    db.commit()
    db.refresh(db_book)
    return db_book

@app.get("/books/", response_model=list[BookSchema])
def read_books(db: SessionLocal = Depends(get_db)):
    return db.query(Book).all()

@app.get("/books/{book_id}", response_model=BookSchema)
def read_book(book_id: int, db: SessionLocal = Depends(get_db)):
    return db.query(Book).filter(Book.id == book_id).first()

@app.put("/books/{book_id}", response_model=BookSchema)
def update_book(book_id: int, book: BookSchema, db: SessionLocal = Depends(get_db)):
    db_book = db.query(Book).filter(Book.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    db_book.title = book.title
    db_book.author = book.author
    db_book.publication_date = book.publication_date
    db.commit()
    return db_book

@app.delete("/books/{book_id}")
def delete_book(book_id: int, db: SessionLocal = Depends(get_db)):
    db_book = db.query(Book).filter(Book.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    db.delete(db_book)
    db.commit()
    return {"message": "Book deleted"}
