from fastapi import FastAPI, Depends
from pydantic import BaseModel
from typing import List
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy import Column, Integer, String
from datetime import datetime

app = FastAPI()

# Database setup
SQLALCHEMY_DATABASE_URL = "postgresql://user:password@localhost/db"

engine = create_engine(SQLALCHEMY_DATABASE_URL)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

Base = declarative_base()

# Model for the database
class Item(Base):
    __tablename__ = "items"

    id = Column(Integer, primary_key=True, index=True)
    title = Column(String, index=True)
    description = Column(String, index=True)
    created_at = Column(datetime, index=True)

# Dependency for getting a database session
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

# Pydantic model for the Item
class ItemModel(BaseModel):
    title: str
    description: str

# GET endpoint for retrieving all items
@app.get("/items/")
def read_items(db: SessionLocal = Depends(get_db)):
    return db.query(Item).all()

# POST endpoint for creating a new item
@app.post("/items/")
def create_item(item: ItemModel, db: SessionLocal = Depends(get_db)):
    db_item = Item(title=item.title, description=item.description, created_at=datetime.now())
    db.add(db_item)
    db.commit()
    db.refresh(db_item)
    return db_item

# GET endpoint for retrieving a single item
@app.get("/items/{item_id}")
def read_item(item_id: int, db: SessionLocal = Depends(get_db)):
    return db.query(Item).filter(Item.id == item_id).first()

# PUT endpoint for updating an item
@app.put("/items/{item_id}")
def update_item(item_id: int, item: ItemModel, db: SessionLocal = Depends(get_db)):
    db_item = db.query(Item).filter(Item.id == item_id).first()
    if db_item is None:
        return {"error": "Item not found"}
    db_item.title = item.title
    db_item.description = item.description
    db.commit()
    db.refresh(db_item)
    return db_item

# DELETE endpoint for deleting an item
@app.delete("/items/{item_id}")
def delete_item(item_id: int, db: SessionLocal = Depends(get_db)):
    db_item = db.query(Item).filter(Item.id == item_id).first()
    if db_item is None:
        return {"error": "Item not found"}
    db.delete(db_item)
    db.commit()
    return {"message": "Item deleted"}
