from sqlalchemy.orm import sessionmaker
from pydantic import BaseModel

app = FastAPI()

# PostgreSQL database configuration
DB_HOST = 'db'
DB_NAME = 'books'
DB_USER = 'postgres'
DB_PASSWORD = 'password'

engine = create_engine(f'postgresql://{DB_USER}:{DB_PASSWORD}@{DB_HOST}/{DB_NAME}')
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

Base = declarative_base()

# Book model
class Book(Base):
    __tablename__ = 'books'
    id = Column(Integer, primary_key=True)
    title = Column(String)
    author = Column(String)

# Create database tables
Base.metadata.create_all(engine)

# API endpoints
@app.get("/books/")
def read_books():
    session = SessionLocal()
    books = session.query(Book).all()
    return [{"id": b.id, "title": b.title, "author": b.author} for b in books]

@app.post("/books/")
def create_book(book: Book):
    session = SessionLocal()
    session.add(book)
    session.commit()
    return {"id": book.id, "title": book.title, "author": book.author}

@app.get("/books/{book_id}")
def read_book(book_id: int):
    session = SessionLocal()
    book = session.query(Book).filter(Book.id == book_id).first()
    if book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    return {"id": book.id, "title": book.title, "author": book.author}

@app.put("/books/{book_id}")
def update_book(book_id: int, book: Book):
    session = SessionLocal()
    book_to_update = session.query(Book).filter(Book.id == book_id).first()
    if book_to_update is None:
        raise HTTPException(status_code=404, detail="Book not found")
    book_to_update.title = book.title
    book_to_update.author = book.author
    session.commit()
    return {"id": book_to_update.id, "title": book_to_update.title, "author": book_to_update.author}

@app.delete("/books/{book_id}")
def delete_book(book_id: int):
    session = SessionLocal()
    book_to_delete = session.query(Book).filter(Book.id == book_id).first()
    if book_to_delete is None:
        raise HTTPException(status_code=404, detail="Book not found")
    session.delete(book_to_delete)
    session.commit()
    return {"message": "Book deleted"}
