# main.py
from fastapi import FastAPI, Depends, HTTPException
from pydantic import BaseModel
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from typing import List

app = FastAPI()

class Book(BaseModel):
    id: int
    title: str
    author: str

class BookDB(BaseModel):
    id: int
    title: str
    author: str

# Create a database engine
engine = create_engine("postgresql://user:password@host:port/dbname")

# Create a configured "Session" class
Session = sessionmaker(bind=engine)

# Create a session object
session = Session()

# Create a FastAPI endpoint to handle CRUD operations
@app.get("/books/", response_model=List[BookDB])
async def read_books():
    return session.query(BookDB).all()

@app.post("/books/", response_model=BookDB)
async def create_book(book: Book):
    db_book = BookDB(id=book.id, title=book.title, author=book.author)
    session.add(db_book)
    session.commit()
    return db_book

@app.get("/books/{book_id}", response_model=BookDB)
async def read_book(book_id: int):
    return session.query(BookDB).filter(BookDB.id == book_id).first()

@app.put("/books/{book_id}", response_model=BookDB)
async def update_book(book_id: int, book: BookDB):
    db_book = session.query(BookDB).filter(BookDB.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    db_book.title = book.title
    db_book.author = book.author
    session.commit()
    return db_book

@app.delete("/books/{book_id}")
async def delete_book(book_id: int):
    db_book = session.query(BookDB).filter(BookDB.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    session.delete(db_book)
    session.commit()
    return {"message": "Book deleted"}
