# Create a database engine
from sqlalchemy import create_engine
engine = create_engine("postgresql://user:password@localhost:5432/db")

# Create a metadata object
from sqlalchemy.orm import sessionmaker
SessionLocal = sessionmaker(bind=engine)

# Define a function to get a database session
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

# Define API endpoints
@app.get("/posts/")
async def read_posts():
    db = next(get_db())
    posts = db.query(Post).all()
    return posts

@app.post("/posts/")
async def create_post(post: Post):
    db = next(get_db())
    db.add(post)
    db.commit()
    return post

@app.get("/posts/{post_id}")
async def read_post(post_id: int):
    db = next(get_db())
    post = db.query(Post).get(post_id)
    return post

@app.put("/posts/{post_id}")
async def update_post(post_id: int, post: Post):
    db = next(get_db())
    post_to_update = db.query(Post).get(post_id)
    if post_to_update:
        post_to_update.title = post.title
        post_to_update.content = post.content
        db.commit()
        return post_to_update
    return {"error": "Post not found"}

@app.delete("/posts/{post_id}")
async def delete_post(post_id: int):
    db = next(get_db())
    post_to_delete = db.query(Post).get(post_id)
    if post_to_delete:
        db.delete(post_to_delete)
        db.commit()
        return {"message": "Post deleted"}
    return {"error": "Post not found"}
