### User Authentication

We'll use the `fastapi-security` library to implement JWT token-based authentication.

**`main.py`**
```python
from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from pydantic import BaseModel
from jose import jwt
from passlib.context import CryptContext

app = FastAPI()

# Define a Pydantic model for the user
class User(BaseModel):
    username: str
    email: str
    password: str

# Define a password hasher
pwd_context = CryptContext(schemes=["bcrypt"], default="bcrypt")

# Define a JWT secret key
secret_key = "your_secret_key_here"

# Define a GraphQL mutation for user registration
@app graphql mutation
async def register_user(user: User):
    # Hash the password and store it in the database
    hashed_password = pwd_context.hash(user.password)
    # Create a new user in the database
    db_user = User(username=user.username, email=user.email, password=hashed_password)
    db.add(db_user)
    db.commit()
    return {"message": "User created successfully"}

# Define a GraphQL mutation for user login
@app graphql mutation
async def login_user(username: str, password: str):
    # Retrieve the user from the database
    user = db.query(User).filter(User.username == username).first()
    if not user or not pwd_context.verify(password, user.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    # Generate a JWT token
    access_token = jwt.encode({"sub": user.username}, secret_key, algorithm="HS256")
    return {"access_token": access_token}
