    title = Column(String, nullable=False)
    author = Column(String, nullable=False)
    publication_date = Column(DateTime, nullable=False)

Base.metadata.create_all(engine)

# Dependency
def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

# JWT authentication
def authenticate_user(username: str, password: str):
    # Authentication logic here
    return username == "admin" and password == "password"

def get_token(username: str):
    access_token_expires = timedelta(minutes=15)
    access_token = jwt.encode(
        {"username": username, "exp": datetime.utcnow() + access_token_expires},
        JWT_SECRET_KEY,
        algorithm="HS256",
    )
    return access_token

@app.post("/login")
async def login(username: str, password: str):
    if not authenticate_user(username, password):
        raise HTTPException(status_code=401, detail="Invalid username or password")
    return {"access_token": get_token(username)}

# Book endpoints
class BookSchema(BaseModel):
    title: str
    author: str
    publication_date: str

@app.post("/books/")
async def create_book(book: BookSchema, db: SessionLocal = Depends(get_db)):
    db_book = Book(title=book.title, author=book.author, publication_date=book.publication_date)
    db.add(db_book)
    db.commit()
    db.refresh(db_book)
    return db_book

@app.get("/books/")
async def read_books(db: SessionLocal = Depends(get_db)):
    return db.query(Book).all()

@app.get("/books/{book_id}")
async def read_book(book_id: int, db: SessionLocal = Depends(get_db)):
    return db.query(Book).filter(Book.id == book_id).first()

@app.put("/books/{book_id}")
async def update_book(book_id: int, book: BookSchema, db: SessionLocal = Depends(get_db)):
    db_book = db.query(Book).filter(Book.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    db_book.title = book.title
    db_book.author = book.author
    db_book.publication_date = book.publication_date
    db.commit()
    db.refresh(db_book)
    return db_book

@app.delete("/books/{book_id}")
async def delete_book(book_id: int, db: SessionLocal = Depends(get_db)):
    db_book = db.query(Book).filter(Book.id == book_id).first()
    if db_book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    db.delete(db_book)
    db.commit()
    return {"message": "Book deleted successfully"}
