from datetime import datetime, timedelta
import redis
import memcache
from jose import jwt, JWTError

app = FastAPI()

# Redis and Memcached connections
redis_conn = redis.Redis(host='localhost', port=6379, db=0)
memcache_conn = memcache.Client(['127.0.0.1:11211'])
