**Step 2: User Management System**

Implement user registration, login, and retrieval of user profiles:
```python
class User(BaseModel):
    username: str
    email: str
    password: str

class UserInDB(User):
    id: int

pwd_context = CryptContext(schemes=["bcrypt"], default="bcrypt")
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

@app.post("/register")
async def register_user(user: UserInDB):
    hashed_password = pwd_context.hash(user.password)
    redis_conn.set(user.username, hashed_password)
    memcache_conn.set(user.username, hashed_password)
    return {"message": "User registered successfully"}

@app.post("/login")
async def login_user(form_data: OAuth2PasswordRequestForm = Depends()):
    user = form_data.username
    password = form_data.password
    stored_hash = redis_conn.get(user)
    if stored_hash:
        if pwd_context.verify(password, stored_hash):
            access_token = jwt.encode({"sub": user}, "secret_key", algorithm="HS256")
            return {"access_token": access_token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{username}")
async def get_user_profile(username: str):
    stored_hash = redis_conn.get(username)
    if stored_hash:
        return {"username": username}
    else:
        return {"message": "User not found"}
```
**Step 3: Redis Caching**

Implement a decorator to cache user profiles for a specified time (e.g., 1 hour):
```python
from functools import wraps
from datetime import datetime, timedelta

def cache_user_profile(ttl=3600):
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            username = kwargs.get("username")
            cached_response = redis_conn.get(f"user:{username}")
            if cached_response:
                return cached_response
            else:
                response = await func(*args, **kwargs)
                redis_conn.setex(f"user:{username}", ttl, response)
                memcache_conn.setex(f"user:{username}", ttl, response)
                return response
        return wrapper
    return decorator

@app.get("/users/{username}")
@cache_user_profile(ttl=3600)
async def get_user_profile(username: str):
    stored_hash = redis_conn.get(username)
    if stored_hash:
        return {"username": username}
    else:
        return {"message": "User not found"}
```
